-- Siembra de scene.prompt.blocks (Feature 009, Fase 5b, #20; T1303; Nivel 2 pre-autorizada por Neo; REQ-CFG9-005, NFR-009-002; SC-009-024).
-- @implements REQ-CFG9-005, NFR-009-002
-- Migracion NUEVA y ADITIVA: inserta UNA fila en platform_parameters con el JSON de los 6 bloques vigentes (byte a byte, DEFAULT_PROMPT_BLOCKS); no crea ni altera tablas ni edita migraciones previas.
-- updated_by_user_id NULL (la siembra no tiene autor). No siembra modelo, region ni tope global (siguen por entorno). ON CONFLICT DO NOTHING respeta una fila existente.
-- Equivale a la 0022 de SQLite. Sin BEGIN/COMMIT: el migrador corre cada migracion en una transaccion.
INSERT INTO platform_parameters (key, value, description, updated_at, updated_by_user_id)
VALUES ('scene.prompt.blocks', '{"STYLE_BASE_TEXT":"Create a single cohesive 16-bit cozy retro RPG isometric pixel art cutaway illustration of a sunlit home living room. Crisp pixel clusters, clean pixel-art outlines, flat warm indie-game shading, and a harmonious palette of warm forest green, soft pastel mint, warm cream, honey wood, and gentle sky blue. Include cozy pet-care details like ceramic food and water bowls, potted houseplants, and soft natural morning light.","HOUSEHOLD_WITH_PHOTO":"Draw a brand-new 16-bit retro RPG isometric cutaway room diorama inspired by the furniture, plants, color accents, and general room layout of {photoRef}.","HOUSEHOLD_GENERIC":"Design a warm, cozy modern living room interior with honey-colored wooden floors, a soft armchair, pet beds, and a large sunlit window.","PRESERVATION_BLOCK":"Translate the pet from the reference photos into a single cohesive 16-bit isometric pixel art illustration. Faithfully preserve each pet species, fur colors, coat patterns, ear shapes, body proportions, and unique markings from the photos so each one is clearly recognizable.","PIXEL_REDRAW_RULE":"Render every wall, floor tile, piece of furniture, plant, and pet as crisp 16-bit retro RPG video-game pixel art with clearly visible individual pixels, sharp pixel-art outlines, and flat cozy indie-game shading.","STYLE_CLOSING":"Match the exact 16-bit isometric RPG pixel art style, warm natural lighting, and cozy palette."}', 'Bloques del prompt de la escena', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), NULL)
ON CONFLICT (key) DO NOTHING;
